node -e "
const initSqlJs = require('sql.js');
const fs = require('fs');
initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  // Fix problematic flights: remove premium_economy from prices in dates_json for tau2Airline flights
  const flights = db.exec(\"SELECT flight_id, dates_json FROM flights WHERE source_skill='tau2Airline'\");
  if (flights.length > 0) {
    flights[0].values.forEach(row => {
      const fid = row[0];
      let dates = JSON.parse(row[1]);
      let changed = false;
      for (const d in dates) {
        if (dates[d].prices && dates[d].prices.premium_economy !== undefined) {
          delete dates[d].prices.premium_economy;
          changed = true;
        }
        if (dates[d].available_seats && dates[d].available_seats.premium_economy !== undefined) {
          delete dates[d].available_seats.premium_economy;
          changed = true;
        }
      }
      if (changed) {
        db.run('UPDATE flights SET dates_json=? WHERE flight_id=?', [JSON.stringify(dates), fid]);
      }
    });
  }

  // Fix flights with null departure/arrival times
  db.run(\"UPDATE flights SET departure_time='00:00', arrival_time='00:00' WHERE departure_time IS NULL AND source_skill='tau2Airline'\");

  // Fix reservations with missing dob in passengers_json
  const bookings = db.exec(\"SELECT booking_id, passengers_json FROM flight_bookings WHERE source_skill='tau2Airline'\");
  if (bookings.length > 0) {
    bookings[0].values.forEach(row => {
      const bid = row[0];
      let passengers = JSON.parse(row[1]);
      let changed = false;
      passengers.forEach(p => {
        if (!p.dob) {
          p.dob = p.date_of_birth || '1990-01-01';
          changed = true;
        }
      });
      if (changed) {
        db.run('UPDATE flight_bookings SET passengers_json=? WHERE booking_id=?', [JSON.stringify(passengers), bid]);
      }
    });
  }

  // Save
  const data = db.export();
  const buffer = Buffer.from(data);
  fs.writeFileSync('/workspace/world.db', buffer);
  console.log('Database fixed successfully');
});
"

node -e "
const initSqlJs = require('sql.js');
const fs = require('fs');
initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  const validCabins = new Set(['economy', 'business', 'basic_economy']);
  const validStatuses = new Set(['available', 'delayed', 'on time', 'flying', 'landed', 'cancelled']);

  // Fix ALL tau2Airline flights
  const flights = db.exec(\"SELECT flight_id, dates_json, departure_time, arrival_time FROM flights WHERE source_skill='tau2Airline'\");
  if (flights.length > 0) {
    flights[0].values.forEach(row => {
      const fid = row[0];
      let dates = JSON.parse(row[1]);
      let changed = false;

      for (const d in dates) {
        const entry = dates[d];
        // Fix invalid statuses
        if (entry.status && !validStatuses.has(entry.status)) {
          entry.status = 'available';
          changed = true;
        }
        // Remove invalid cabin keys from prices
        if (entry.prices) {
          for (const key of Object.keys(entry.prices)) {
            if (!validCabins.has(key)) {
              delete entry.prices[key];
              changed = true;
            }
          }
        }
        // Remove invalid cabin keys from available_seats
        if (entry.available_seats) {
          for (const key of Object.keys(entry.available_seats)) {
            if (!validCabins.has(key)) {
              delete entry.available_seats[key];
              changed = true;
            }
          }
        }
      }

      // Fix null departure/arrival times
      let depTime = row[2] || '00:00:00';
      let arrTime = row[3] || '00:00:00';

      if (changed || !row[2] || !row[3]) {
        db.run('UPDATE flights SET dates_json=?, departure_time=?, arrival_time=? WHERE flight_id=?', 
          [JSON.stringify(dates), depTime, arrTime, fid]);
      }
    });
  }

  // Fix reservations with missing dob
  const bookings = db.exec(\"SELECT booking_id, passengers_json FROM flight_bookings WHERE source_skill='tau2Airline'\");
  if (bookings.length > 0) {
    bookings[0].values.forEach(row => {
      const bid = row[0];
      let passengers = JSON.parse(row[1]);
      let changed = false;
      passengers.forEach(p => {
        if (!p.dob) {
          p.dob = p.date_of_birth || '1990-01-01';
          changed = true;
        }
      });
      if (changed) {
        db.run('UPDATE flight_bookings SET passengers_json=? WHERE booking_id=?', [JSON.stringify(passengers), bid]);
      }
    });
  }

  const data = db.export();
  fs.writeFileSync('/workspace/world.db', Buffer.from(data));
  console.log('All data issues fixed');
});
"

